} Node;
Node* lca(Node*r, int p, int q) {
    if (!r||r->v==p||r->v==q)return r;
    Node*l=lca(r->l, p, q), *ri=lca(r->r, p, q);
    if (l&&ri)return r;
    return l?l:ri;
}

